// Filter leads due for Step 2 or Step 3
// Step 2: status=emailed-step1 AND step1 sent 3+ days ago AND no reply
// Step 3: status=emailed-step2 AND step2 sent 4+ days ago AND no reply

const items = $input.all();
const today = new Date();
const outputItems = [];

for (const item of items) {
  const lead = item.json;
  const status = lead['Status'];
  const replyReceived = lead['Reply Received'];
  const doNotContact = lead['Do Not Contact'];

  // Skip if replied or DNC
  if (replyReceived === 'yes' || doNotContact === 'TRUE' || doNotContact === true) {
    continue;
  }

  let readyForFollowup = false;
  let followupStep = null;

  if (status === 'emailed-step1') {
    const sentDate = new Date(lead['Step 1 Sent Date']);
    const daysSinceSent = Math.floor((today - sentDate) / (1000 * 60 * 60 * 24));
    if (daysSinceSent >= 3) {
      readyForFollowup = true;
      followupStep = 'step2';
    }
  } else if (status === 'emailed-step2') {
    const sentDate = new Date(lead['Step 2 Sent Date']);
    const daysSinceSent = Math.floor((today - sentDate) / (1000 * 60 * 60 * 24));
    if (daysSinceSent >= 4) {
      readyForFollowup = true;
      followupStep = 'step3';
    }
  }

  if (readyForFollowup) {
    outputItems.push({
      json: { ...lead, followupStep }
    });
  }
}

// Enforce daily limit: max 20 per inbox across all workflows combined
// Simple approach: cap total follow-ups at 30 per run
return outputItems.slice(0, 30);

// Build the correct follow-up email based on step and clinic type
const items = $input.all();
const outputItems = [];

for (const item of items) {
  const lead = item.json;
  const step = lead.followupStep;
  const clinicType = (lead['Clinic Type'] || 'dental').toLowerCase();
  const firstName = lead['First Name'] || lead['Contact Name'] || 'there';
  const businessName = lead['Business Name'];
  const city = lead['City'] || 'your area';

  let subject = '';
  let body = '';

  if (step === 'step2') {
    // STEP 2 — Follow-Up 1 (reply to same thread conceptually)
    if (clinicType === 'dental' || clinicType === 'orthodontics') {
      subject = `Re: Quick question for ${firstName}`;
      body = `Hi ${firstName},

Just bumping this up — I know inboxes get busy.

One thing I've seen work really well for practices like ${businessName}: setting up a simple "refer a friend" system that your front desk can run in 5 minutes/day. No app, no tech. Just a process.

The practices that do this consistently see 2–3 extra new patients per month from existing patients alone.

Happy to walk you through it on a quick call — no pitch, just want to show you the framework.

Worth 15 minutes?

[YOUR NAME]`;
    } else {
      subject = `Re: Quick idea for ${businessName}`;
      body = `Hi ${firstName},

Following up in case this got buried.

One quick stat that might be relevant: aesthetic clinics typically see 60–70% of revenue come from repeat clients — but most don't have a system to bring them back predictably.

I've helped a few practices set up a simple reactivation sequence (email + text) that brings back dormant clients almost on autopilot. Takes about a day to set up.

If that sounds interesting, I'd love to show you how it works on a short call.

[YOUR NAME]`;
    }
  } else if (step === 'step3') {
    // STEP 3 — Final Touch
    if (clinicType === 'dental' || clinicType === 'orthodontics') {
      subject = `Last note — ${businessName}`;
      body = `Hi ${firstName},

I'll keep this short — last email from me on this.

I put together a quick overview of what I've seen work for dental practices in ${city} specifically. Happy to send it over if useful (it's a one-pager, no fluff).

If timing isn't right, totally understand. I'll check back in a few months.

Either way — good luck with ${businessName}. The reviews look great.

[YOUR NAME]

P.S. If you ever want that one-pager, just reply "send it" and I'll get it to you.`;
    } else {
      subject = `Closing the loop — ${businessName}`;
      body = `Hi ${firstName},

Last note from me — don't want to clutter your inbox.

I wrote up a short breakdown of the 3 things aesthetic clinics in ${city} are doing right now to grow without ads. Happy to send it over if you're curious.

No strings. Just figured it might be useful given what ${businessName} is building.

If now isn't the right time, no worries at all — I'll circle back later in the year.

[YOUR NAME]

P.S. Reply "yes" if you want the breakdown — I'll send it right over.`;
    }
  }

  outputItems.push({
    json: {
      ...lead,
      emailSubject: subject,
      emailBody: body
    }
  });
}

return outputItems;

// Determine new status and update dates
const item = $input.item.json;
const today = new Date().toISOString().split('T')[0];
const step = item.followupStep;

let newStatus = '';
let sentDateField = '';
let nextActionDate = '';

if (step === 'step2') {
  newStatus = 'emailed-step2';
  sentDateField = 'Step 2 Sent Date';
  const next = new Date();
  next.setDate(next.getDate() + 4);
  nextActionDate = next.toISOString().split('T')[0];
} else if (step === 'step3') {
  newStatus = 'emailed-step3';
  sentDateField = 'Step 3 Sent Date';
  nextActionDate = ''; // Sequence complete
}

return [{
  json: {
    'Lead ID': item['Lead ID'],
    Status: newStatus,
    [sentDateField]: today,
    'Next Action Date': nextActionDate,
    // Also log to Sent Log
    _logEntry: {
      Timestamp: new Date().toISOString(),
      'Lead ID': item['Lead ID'],
      'Business Name': item['Business Name'],
      Email: item['Email'],
      Step: step === 'step2' ? '2' : '3',
      'Inbox Used': item['Assigned Inbox'],
      Subject: item['emailSubject'],
      Status: 'sent'
    }
  }
}];
